-- Complete scheduled deliveries through the existing atomic dispatch transaction.
alter table public.stock_ledger drop constraint if exists stock_ledger_source_type;
alter table public.stock_ledger add constraint stock_ledger_source_type check(source_transaction_type in('GRN','PRODUCTION_ENTRY','PACKING_RECORD','DISPATCH','ADJUSTMENT','OPENING_BALANCE','TRANSFER','MATERIAL_ISSUE'));
alter table public.dispatches add column dispatch_schedule_id uuid unique references public.dispatch_schedules(dispatch_schedule_id);
create or replace function public.dispatch_scheduled_goods(p_schedule uuid,p_gate_pass uuid,p_vehicle text,p_driver text,p_dispatcher text)returns uuid language plpgsql security definer set search_path=public as $$declare v_finished uuid;v_dispatch uuid;v_status text;begin if not has_factory_role(auth.uid(),array['admin','store'])then raise exception'not authorized';end if;select finished_goods_id,status into v_finished,v_status from dispatch_schedules where dispatch_schedule_id=p_schedule for update;if v_finished is null or v_status not in('PLANNED','READY')then raise exception'schedule is not open for dispatch';end if;select dispatch_finished_goods(v_finished,p_gate_pass,p_vehicle,p_driver,p_dispatcher)into v_dispatch;update dispatches set dispatch_schedule_id=p_schedule,updated_at=now(),updated_by=auth.uid()::text where dispatch_id=v_dispatch;update dispatch_schedules set status='DISPATCHED',vehicle_no=coalesce(p_vehicle,vehicle_no),driver_name=coalesce(p_driver,driver_name),updated_at=now(),updated_by=auth.uid()::text where dispatch_schedule_id=p_schedule;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Scheduled Dispatch Completed','dispatch_schedules',p_schedule,jsonb_build_object('dispatch_id',v_dispatch,'gate_pass_id',p_gate_pass));return v_dispatch;end$$;
grant execute on function public.dispatch_scheduled_goods(uuid,uuid,text,text,text)to authenticated;
